import json, os
mf = json.load(open('inputs/manifest.json'))
print(json.dumps(mf)[:1800])
paths=[]
for root,_,files in os.walk('.'):
    for f in files:
        if f.lower().endswith(('.csv','.xlsx','.xls')):
            paths.append(os.path.join(root,f))
print('FILES', paths[:10])
for p in paths:
    if 'artikel' in p.lower():
        data=open(p,'rb').read()
        print('PATH', p, 'BYTES', len(data))
        txt=data.decode('utf-8-sig', errors='replace')
        lines=txt.splitlines()
        print('NLINES', len(lines))
        for i,l in enumerate(lines[:4]):
            print(i, repr(l))
        for i,l in enumerate(lines[-2:], start=max(0,len(lines)-2)):
            print(i, repr(l))

